window.kbPageData["views/entry/k-0565b75e74d2a2a9"] = {"key":"entry/k-0565b75e74d2a2a9","state":{"route":"entry/k-0565b75e74d2a2a9"},"node":{"id":"k-0565b75e74d2a2a9","mode":"k","title":"扎实推进乡村全面振兴","type":"事实与事件","domain":"公共管理","reading":"","intro":"","priority":100,"aliases":[],"qs":[],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":true,"tags":{"专题":["rural"],"主类":["事实与事件"],"出处性质":["报告摘登"],"学科":["公共管理","经济"],"时间索引":["年度事件或数据"],"来源主题":["年度政府工作"],"资料类别":["时政"]},"eventTags":[{"year":2026,"title":"政府工作报告","slug":"94fd2d7ef9a6"}],"directorySummary":"持续推进农村改革发展。全面开展第二轮土地承包到期后再延长 30 年整省试点①，发\n展农业适度规模经营，健全现代农业经营体系和社会化服务体系②。支持发展新型农村集体\n经济③。深化集体产权、集体林权、农垦、供销社等改革。开展第四次全国农业普查④。推动\n城乡要素双向流动，深化农文旅等融合发展，培育壮大乡村…","sources":[{"id":"b380da2bf8353e74","label":"扎实推进乡村全面振兴","topic":"年度政府工作","category":"时政","text":"持续推进农村改革发展。全面开展第二轮土地承包到期后再延长 30 年整省试点①，发\n展农业适度规模经营，健全现代农业经营体系和社会化服务体系②。支持发展新型农村集体\n经济③。深化集体产权、集体林权、农垦、供销社等改革。开展第四次全国农业普查④。推动\n城乡要素双向流动，深化农文旅等融合发展，培育壮大乡村特色产业，提高农产品精深加工\n水平，发展林下经济，完善联农带农机制，促进农民稳定增收。发展壮大乡村人才队伍。深\n化农村移风易俗，提升乡村治理和文明乡风建设水平。持续整治提升农村人居环境，以钉\n钉子精神⑤解决好农村改厕、垃圾围村等问题。扎实推进全域土地综合整治。完善乡村建设\n实施机制，加快补齐农村现代生活条件短板，推进宜居宜业和美乡村建设。","source":{"doc":"6cbfb01fe723bba64b75","first":35,"last":35,"page":35,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"e1c73e651b4ca724","label":"扎实推进乡村全面振兴","topic":"年度政府工作","category":"时政","text":"（六）扎实推进乡村全面振兴。坚持把“三农”①工作作为重中之重，深入学习运用“千\n万工程”②经验，提高强农惠农富农政策效能，进一步夯实农业农村基础、提升发展质效。\n毫不放松抓好粮食生产。坚持产量产能、生产生态、增产增收一起抓，加力实施新一\n轮千亿斤粮食产能提升行动。稳定粮油生产，促进良田良种良机良法集成增效，推动大面积\n单产提高、品种培优、品质提升。巩固提升大豆油料产能，推动棉糖胶等稳产提质。坚持农\n林牧渔并举，增加多元食物供给③。严守耕地红线④，严格占补平衡管理，高质量推进高标\n准农田⑤建设，加强黑土地保护和盐碱地综合利用。制定促进农业保险发展的措施。提高农\n业综合防灾减灾能力。深入实施种业振兴⑥行动，加快选育推广突破性品种，推进先进适用\n农机装备研发应用，打通农业科技推广“最后一公里”。统筹生产、收储等政策，促进粮食\n等重要农产品价格保持在合理水平，实施粮食产销区省际横向利益补偿，调动主产区和农民\n种粮积极性。各地区都要扛稳责任，共同端牢中国人的饭碗。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":33,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"},{"id":"c982988738a573a2","label":"扎实推进乡村全面振兴","topic":"年度政府工作","category":"时政","text":"实施常态化精准帮扶。持续巩固拓展脱贫攻坚成果，把常态化帮扶纳入乡村振兴战略①\n统筹实施，守牢不发生规模性返贫致贫底线。保持帮扶政策总体稳定。合理确定防止返贫\n致贫对象认定标准，做好监测识别，确保早发现、早干预、早帮扶。提高产业、就业等开发\n式帮扶②实效，发挥社会救助③兜底保障作用。继续做好易地搬迁后续扶持。完善东西部协作、\n定点帮扶、驻村帮扶和消费帮扶等。分层分类帮扶欠发达地区，支持乡村振兴重点帮扶县加\n快发展，增强内生动力。","source":{"doc":"6cbfb01fe723bba64b75","first":34,"last":35,"page":34,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"报告摘登"}]},"questions":{},"terms":{},"references":{},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"}],"units":{"k-0565b75e74d2a2a9":[]}};
